import{_ as n,C as r,o as c,c as h,j as t,a as o,E as a,ah as i}from"./chunks/framework.BpF7DVZ1.js";const P=JSON.parse('{"title":"输入组","description":"","frontmatter":{},"headers":[],"relativePath":"components/input-group.md","filePath":"components/input-group.md","lastUpdated":1788644314000}'),s={name:"components/input-group.md"},p={id:"输入组",tabindex:"-1"};function u(b,e,m,f,x,g){const l=r("Badge"),d=r("XhDemo");return c(),h("div",null,[t("h1",p,[e[0]||(e[0]=o("输入组 ",-1)),a(l,{type:"info",text:"input-group"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#输入组","aria-label":'Permalink to "输入组 <Badge type="info" text="input-group" />"'},"​",-1))]),e[3]||(e[3]=i('<p>把输入框与它的前后缀、动作按钮拼成一个盒：相邻两段共用一条边，圆角只留在两端。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一个输入框需要固定的前后缀说明它填什么（<code>https://</code> 打头、<code>.com</code> 收尾、单位、币种）。</li><li>输入框后面紧跟一个作用在它身上的动作（搜索、复制、提交）。</li><li>几个控件填的是同一件事的不同部分（区号 + 号码），想让它们看起来是一个控件。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>组内几段是并列的动作、彼此不围绕同一个输入：那是<a href="./button-group">按钮组</a>。</li><li>前后缀要跟着输入内容变、或者本身可点：把它做成组里的一枚<a href="./button">按钮</a>或<a href="./select">选择器</a>， 别塞进 <code>item</code>——<code>item</code> 是不可交互的固定文本。</li><li>只是想让两个控件挨着：留间距摆开就行，拼成一体会让人以为它们必须一起填。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>两个部件：<code>root</code> 是组容器，<code>item</code> 是前后缀块；组内的控件是作者自己的节点。</li><li>中缝合并：后一段回挪一个描边宽度，两条边叠成一条，组里看不到双线。</li><li>圆角只留在首尾两端，中间各段收平；用逻辑角属性写，rtl 下自动换边。</li><li>悬停或拿到焦点的那一段抬到最上层，聚焦环不会被邻座的底色和描边切掉一半。</li><li>档位跟着组内控件走：组里有 <code>sm</code> 的控件，<code>item</code> 就是 <code>sm</code>；也可以在组上写 <code>size</code> 直接指定。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>前后缀与输入框拼成一个盒：中缝合成一条，圆角只留在两端</p>',10)),a(d,{src:"input-group/01-basic"}),e[4]||(e[4]=t("h3",{id:"搭动作钮",tabindex:"-1"},[o("搭动作钮 "),t("a",{class:"header-anchor",href:"#搭动作钮","aria-label":'Permalink to "搭动作钮"'},"​")],-1)),e[5]||(e[5]=t("p",null,"按钮作用在紧挨着它的那个输入框上，两段共用中缝那条边",-1)),a(d,{src:"input-group/02-action"}),e[6]||(e[6]=t("h3",{id:"尺寸档",tabindex:"-1"},[o("尺寸档 "),t("a",{class:"header-anchor",href:"#尺寸档","aria-label":'Permalink to "尺寸档"'},"​")],-1)),e[7]||(e[7]=t("p",null,"前后缀块跟着组内控件自己的档走，组上不必把同一档再写一遍",-1)),a(d,{src:"input-group/03-size"}),e[8]||(e[8]=t("h3",{id:"区间输入",tabindex:"-1"},[o("区间输入 "),t("a",{class:"header-anchor",href:"#区间输入","aria-label":'Permalink to "区间输入"'},"​")],-1)),e[9]||(e[9]=t("p",null,"组里放两个输入框，中间夹一个前后缀块当连接词：三段共用两条中缝，圆角只留在最外两端；两头各自带 aria-label，读屏分得清哪个是起点",-1)),a(d,{src:"input-group/04-range"}),e[10]||(e[10]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-input-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhInputGroupItem</code> <code>XhInputGroupRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/input-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;input-group&quot;</code>：<strong><code>root</code></strong> · <code>item</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，落到根上供皮肤写进 item 的高度、内衬与字号槽位。 不写时档位由组内控件自己的 data-size 决定，组里没有带档的控件就走 md。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/input-group.css</code> 按部件选择：<code>[data-scope=&quot;input-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-input-group-item-bg</code> · <code>--xh-input-group-item-border</code> · <code>--xh-input-group-item-fg</code> · <code>--xh-input-group-item-font-size</code> · <code>--xh-input-group-item-h</code> · <code>--xh-input-group-item-px</code> · <code>--xh-input-group-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>border-color</code> · <code>color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>组里放<a href="./text-field">输入框</a>、<a href="./number-field">数字输入框</a>、<a href="./select">选择器</a>、<a href="./button">按钮</a>。</li><li>要带标签与校验提示时，把整个组放进<a href="./field">表单域</a>，标签与提示由它给。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>一组以三到四段为宜：段越多，哪一段是可填的就越难一眼看出来。</li><li>前后缀写成静态文本，别放会变的值——它长在框上，看起来像是已经填好的内容。</li><li>组里各控件写同一个尺寸档，或者干脆都不写：混档会让中缝对不齐。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用 <code>item</code> 装可点的东西：它不出角色也不接键盘，读屏用户不知道那里能点。</li><li>靠负外边距在业务代码里自己拼中缝：改一次描边宽度就得把每一处拼法翻一遍。</li></ul>',32))])}const k=n(s,[["render",u]]);export{P as __pageData,k as default};
